function IdolLive3D_MainForEdit:__init()
    self.controller = nil
    self.freeTrackjsonData_100 = nil
    self.freeTrackjsonData_200 = nil

    self.isInit = false
end


function IdolLive3D_MainForEdit:__delete()
end



function IdolLive3D_MainForEdit:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    -- PC / Mobile 平台:
    if IdolLive3D_States.expectedPlatformType == IdolLive3D_States.PlatformType.Auto then 
        IdolLive3D_States.isWindowsPlatform = IdolLive3D_Utils.IsReallyPCPlatform() 
    else 
        IdolLive3D_States.isWindowsPlatform = (self.expectedPlatformType == IdolLive3D_States.PlatformType.PC)
    end 

    self:_InitForEditMode()
end



-- 单场景运行不再存在 loader 脚本了, 用此处的 同步加载来 取代: 
function IdolLive3D_MainForEdit:_InitForEditMode()


    -- =============== 临时读取 baseParams json 文件 =============== -- todo: 未来走表

    local params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( params )
    local jsonName  = LuaParametersReader.Read( params, "jsonName", LuaParametersType.String )
    local baseParamsJsonFilePath = "Presets/IdolLive3D/BaseParams/" .. tostring(jsonName) .. ".json"
    -- print("koko - json path: " .. tostring(jsonFilePath))

    self.baseJson = IdolLive3D_BaseParamsJsonData.New( IdolLive3D_Utils.LoadJsonSync( baseParamsJsonFilePath ) )
    
    -- =============== 读取 自由相机轨道 json 文件 ===============
    --local freeTrackJsonPath = self.baseJson.freeTrackJsonPath
    assert( self.baseJson:Get_Idle_100().freeTrackJsonPath )
    assert( self.baseJson:Get_Idle_200().freeTrackJsonPath )
    --self.freeTrackjsonData = IdolLive3D_Utils.LoadJsonSync( freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"
    self.freeTrackjsonData_100 = IdolLive3D_Utils.LoadJsonSync( self.baseJson:Get_Idle_100().freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"
    self.freeTrackjsonData_200 = IdolLive3D_Utils.LoadJsonSync( self.baseJson:Get_Idle_200().freeTrackJsonPath ) -- 比如: "Presets/IdolLive3D/FreeTrack/test1.json"


    -- =================== 手动关闭掉一些容易出错的 root节点 ======================
    do
        self:_SetGameObjectActive( "/vcam_idle_100", false )
        self:_SetGameObjectActive( "/vcam_idle_200", false )
        --...
    end


    -- =========================================
    -- 
    local roleRootTF    = IdolLive3D_MainForEdit._FindRootTransformInSingleScene("/_Role_")
    local runtimeRootTF = IdolLive3D_MainForEdit._FindRootTransformInSingleScene("/_Runtime_")
    local buildsRootTF  = IdolLive3D_MainForEdit._FindRootTransformInSingleScene("/_Builds_")
    if isNull(roleRootTF) or isNull(runtimeRootTF) or isNull(buildsRootTF) then 
        printError("koko - 爱豆场景内缺少节点: _Role_ 或 _Runtime_ 或 _Builds_")
        return
    end 


    -- 场景模型主光源信息:
    do  
        local buildTF = IdolLive3D_MainForEdit._FindFirstChild( buildsRootTF, nil, typeof(Transform), true ) -- 拿现成的角色 
        assert( isNotNull(buildTF) )
        print("buildTF = " .. tostring(buildTF.name))

        --- 配置 主光源 参数:
        local live3DMainLightTF = buildTF:Find("Live3DMainLight")
        if isNotNull(live3DMainLightTF) then 
            local live3DMainLight = KTool.GetComponent(live3DMainLightTF.gameObject, typeof(Light)) -- 场景模型主光源信息携带者
            assert( isNotNull(live3DMainLight) )

            IdolLive3D_MainForEdit.SetMainLight( live3DMainLightTF.rotation, live3DMainLight.color, live3DMainLight.intensity )
            --- 
            CfUtils.SetActive( live3DMainLightTF.gameObject, false ) -- !! MUST
        else 
            printError("场景模型 prefab 内未找到 Live3DMainLight 节点")
        end 

        --- 改写 CameraCustomData:
        local srcCameraTF = buildTF:Find("Camera_OnlyCustomData")
        if isNotNull(srcCameraTF) then 
            IdolLive3D_Utils.CopyCameraCustomData( srcCameraTF )
        end 

    end


    -- ===== 使用皮肤定制的 主光源信息: (选配) ===== -- !!! 暂时先不支持
    -- !! 必须在上面的 场景默认主光源配置 之后
    -- local idolLive3D_MainLightParams = self.baseJson.data.idolLive3D_MainLightParams
    -- if isNotNull(idolLive3D_MainLightParams) and idolLive3D_MainLightParams.isUse == true then 
    --     print("本皮肤自带 场景主光源信息")
    --     IdolLive3D_MainForEdit.SetMainLight( Quaternion.Euler(idolLive3D_MainLightParams.rotation), idolLive3D_MainLightParams.color, idolLive3D_MainLightParams.intensity )
    -- end 


    -- -- 总处理器 prefab:
    local runtimeAllEditParams = IdolLive3D_MainForEdit._FindFirstChild( runtimeRootTF, "", typeof(IdolLive3D_BaseParamsBehaviour) )
    if isNull(runtimeAllEditParams) then 
        printError( "请在 _Runtime_ 节点下放入 IdolLive3D_Edit prefab" )
        return
    end 
    local runtimeTF = runtimeAllEditParams.transform


    -- 角色 animator controller 文件:
    local animatorController = nil
    do
        --local controllerPath =  "RuntimeController/Animator_live3d/103021_live.overrideController"
        local controllerPath = self.baseJson.data.roleAnimatorControllerPath
        if type(controllerPath)~="string" or (#controllerPath == 0) then 
            printError("json 数据 roleAnimatorControllerPath 为空")
            return
        end

        local loader = ResourceModule.LoadBundleSync(controllerPath, nil, true)
        if loader.IsError == true then 
            printError("加载 角色 animator controller 资源失败; path: " .. tostring(controllerPath) )
            return
        end 
        animatorController = loader.ResultObject
        --- loader.ResultObject
        -- local controllerGO = loader:Instantiate()
        -- timelineGO.transform:SetParent( runtimeRootTF )
        -- timelineGO.transform:SetPositionAndRotation( Vector3.zero, Quaternion.identity)
        -- timelineTFMaps[name] = timelineGO.transform
    end



    -- 角色:
    local roleAnimator = IdolLive3D_MainForEdit._FindFirstChild( roleRootTF, nil, typeof(Animator), true ) -- 拿现成的角色 
    if isNull(roleAnimator) then 
        printError( "请在 _Role_ 节点下放入 角色 prefab" )
        return
    end 
    local roleTF = roleAnimator.transform
    roleTF.position = Vector3.zero -- Must

    -- 隐藏 角色 体内 某些节点:
    local lpComps = roleAnimator.transform:GetComponentsInChildren(typeof(LuaParameters),true) -- 包含自己
    for i=0, lpComps.Length-1 do 
        local lpComp = lpComps[i]

        local isFindKey = LuaParametersReader.IsFindKey( lpComp, "HideInLive3D" ) -- 宽泛的检测, 只要找到这个 key 就算成立, 暂不检查它的 type 和 value
        if isFindKey == true then 
            print("深度互动: role 体内发现 标注要隐藏的节点: " .. tostring(lpComp.name) )
            KTool.SetActive( lpComp.gameObject, false )
        end 
    end

    -- 仅在 editor 模式下关闭 头部 box 碰撞体:
    do
        local bcComps = roleAnimator.transform:GetComponentsInChildren(typeof(BoxCollider),true) -- 包含自己
        for i=0, bcComps.Length-1 do 
            local bcComp = bcComps[i]
            if bcComp.name == "Head_M" then 
                bcComp.enabled = false
            end 
        end
    end
    
    ---
    local luaMainTF = runtimeTF:Find("luas/main")
    local idolLive3D_Main = nil
    if isNotNull(luaMainTF) then 
        idolLive3D_Main = IdolLive3D_Utils.GetLuaScr(luaMainTF.gameObject, "Game.IdolLive3D.Edit.IdolLive3D_MainForEdit" )
    end
    if isNull(idolLive3D_Main) then 
        printError("koko - 没找到 IdolLive3D_MainForEdit 脚本")
        return
    end 

    -- timelines prefab:
    local timelineTFMaps = {}
    local timelineInfos = self.baseJson.data.timelineInteractiveStates
    for i=1, table.count(timelineInfos) do
        local name = timelineInfos[i].name 
        local path = timelineInfos[i].timelinePath 

        local timelineTF = IdolLive3D_Utils.LoadPrefabSync( path, runtimeRootTF, "timeline: " .. tostring(name) )
        timelineTFMaps[name] = timelineTF
    end


    -- superTimelines prefab:
    local superTimelineTFMaps = {}
    local superTimelineInfos = self.baseJson.data.superTimelineInteractiveStates
    for i=1, table.count(superTimelineInfos) do
        local superTL = superTimelineInfos[i]
        superTimelineTFMaps[superTL.name] = checkTable(superTimelineTFMaps[superTL.name])

        for j=1, table.count(superTL.clips) do
            local clip = superTL.clips[j]
            local name = tostring( superTL.name .. "." .. clip.clipId ) -- "interact_1001.1"
            local path = clip.timelinePath
            local timelineTF = IdolLive3D_Utils.LoadPrefabSync( path, runtimeRootTF, "superTimeline: " .. tostring(name) )

            superTimelineTFMaps[superTL.name][clip.clipId] = timelineTF
        end
    end

    -- simple fxs prefab: 
    local simpleFxTFMaps = {}
    local simpleIStateInfos = self.baseJson.data.simpleInteractiveStates
    for i=1, table.count(simpleIStateInfos) do
        local iState = simpleIStateInfos[i]
        if string.isEmpty(iState.fxPrefabPath) == false then 
            --print( "load simple fx " .. tostring(iState.name ) )
            local name = iState.name 
            local path = iState.fxPrefabPath

            local fxTF = IdolLive3D_Utils.LoadPrefabSync( path, runtimeRootTF, "simple fx: " .. tostring(name) )
            simpleFxTFMaps[name] = fxTF
        end
    end


    -- idle switch: 
    local idleSwitchTFs = {}
    local idleSwitch = self.baseJson.data.idleSwitch
    if self.baseJson:IsIdleSwitchByButton() or self.baseJson:IsIdleSwitchSupportFromSuperTimeline() then

        local fullScreenFX = idleSwitch.fullScreenFX
        idleSwitchTFs.opTF = IdolLive3D_Utils.LoadPrefabSync( fullScreenFX.opPrefabPath, runtimeRootTF, "idle switch 全屏特效 op " )
        idleSwitchTFs.edTF = IdolLive3D_Utils.LoadPrefabSync( fullScreenFX.edPrefabPath, runtimeRootTF, "idle switch 全屏特效 ed " )                
    end

    idolLive3D_Main:Init( roleTF, runtimeRootTF, timelineTFMaps, superTimelineTFMaps, simpleFxTFMaps, idleSwitchTFs, animatorController )
end




---@param roleTF_ UnityEngine.Transform @ 角色根节点
---@param runtimeRootTF_ UnityEngine.Transform
---@param timelineTFMaps_ table            @ 一组 timelineStates tfs
---@param superTimelineTFMaps_ table        @ 一组 super timelineStates tfs
---@param simpleFxTFMaps_ table
---@param idleSwitchTFs_ table
function IdolLive3D_MainForEdit:Init( roleTF_, runtimeRootTF_, timelineTFMaps_, superTimelineTFMaps_, simpleFxTFMaps_, idleSwitchTFs_, animatorController_ )
    print("=== IdolLive3D_MainForEdit start ===")
    assert( isNotNull(roleTF_) )

    Application.targetFrameRate = 60 -- todo: debug

    ------------------------- 
    self.mainCamera = IdolLive3D_Utils.GetMainCamera()

    -- ==============================
    self.roleTF = roleTF_
    self.roleLookAtController = KTool.GetComponent(self.roleTF.gameObject, typeof(LookAtController))
    self.roleAnimator = KTool.GetComponent(self.roleTF.gameObject, typeof(Animator))
    assert( isNotNull(self.roleLookAtController) and isNotNull(self.roleAnimator) )


    self.roleAnimator.runtimeAnimatorController = nil
    
    -- 主动开启 IK:  
    local lookAtIK = KTool.GetComponent(self.roleTF.gameObject, typeof(LookAtIK))
    assert(lookAtIK)
    lookAtIK.enabled = true


    -- 绑定 customLightDirRelativeCamera.RelativeCamera:
    -- 有些 角色 prefab 可能不带此组件
    local customLightDirRelativeCamera = KTool.GetOrAddComponent(self.roleTF.gameObject, typeof(CustomLightDirRelativeCamera))
    if isNull(customLightDirRelativeCamera) then 
        printError("koko - 异常, role 没绑定 CustomLightDirRelativeCamera 脚本")
        return
    end
    customLightDirRelativeCamera.RelativeCamera = self.mainCamera
    customLightDirRelativeCamera.DelayUpdate = true

    -- 绑定 animator controller: 
    if isNull(animatorController_) then 
        printError("参数 animatorController_ 为空")
    else 
        self.roleAnimator.runtimeAnimatorController = animatorController_
    end 

    ------------------
    assert(self.idolCamera) 
    ---@type IdolLive3D_Camera
    self.idolLive3D_CameraEnv = IdolLive3D_Utils.GetLuaScr(self.idolCamera.gameObject, "Game.IdolLive3D.IdolLive3D_Camera" )
    assert( self.idolLive3D_CameraEnv )
    self.idolLive3D_CameraEnv:Init(self)
    --  启动 入场小动画:
    --self.idolLive3D_CameraEnv:PlayInitAnimation()
    ---
    assert(self.idolInteractive) 
    ---@type IdolLive3D_InteractiveManager
    self.idolLive3D_InteractiveManagerEnv = IdolLive3D_Utils.GetLuaScr(self.idolInteractive.gameObject, "Game.IdolLive3D.Interactive.IdolLive3D_InteractiveManager" )
    assert( self.idolLive3D_InteractiveManagerEnv )
    self.idolLive3D_InteractiveManagerEnv:Init(self, runtimeRootTF_, self.idolLive3D_CameraEnv, lookAtIK, self.roleAnimator, timelineTFMaps_, superTimelineTFMaps_, simpleFxTFMaps_, idleSwitchTFs_ )
    ---
    assert(self.idolTextDebug) 
    ---@type IdolLive3D_TextDebug
    self.idolLive3D_TextDebugEnv = IdolLive3D_Utils.GetLuaScr(self.idolTextDebug.gameObject, "Game.IdolLive3D.IdolLive3D_TextDebug" )
    assert( self.idolLive3D_TextDebugEnv )

    ---@type IdolLive3D_Input
    self.idolLive3D_Input = IdolLive3D_Input.New(self)

    -- 反绑参数:
    self.idolLive3D_InteractiveManagerEnv:BindSimpleTap( self.idolLive3D_Input )
    self.idolLive3D_CameraEnv:BindInput( self.idolLive3D_Input )


    --self:PlayBeginVoice()

    --- 
    self.allRoleTFs = { roleTF_ }
    for _,tf in pairs(timelineTFMaps_) do 
        table.insert( self.allRoleTFs, tf )
    end
    for _,se in pairs(superTimelineTFMaps_) do 
        for __,tf in pairs(se) do
            table.insert( self.allRoleTFs, tf )
        end
    end
    for _,tf in pairs(simpleFxTFMaps_) do 
        table.insert( self.allRoleTFs, tf )
    end

    ---
    local initIdleState = self.baseJson:GetInitIdleState()
    self:OnSwitchIdle( initIdleState.idleType )


    --
    self.isInit = true
end



function IdolLive3D_MainForEdit:OnDestroy()

    IdolLive3D_Utils.StopCoroutine(self.co_1)

    if isNotNull(self.idolLive3D_Input) then 
        self.idolLive3D_Input:Delete() -- !! MUST
    end 
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


