function IdolLive3D_MainForEdit:IsInit()
    return (self.isInit == true)
end



function IdolLive3D_MainForEdit:Update()
    if self.isInit ~= true then 
        return
    end

    --print( "idol update" )
    self.idolLive3D_Input:SelfUpdate()
    self.idolLive3D_InteractiveManagerEnv:SelfUpdate()
    self.idolLive3D_CameraEnv:SelfUpdate()
end


