local ResourceModule = CS.Engine.Modules.ResourceModule


function IdolLive3D_MainForEdit._FindRootTransformInSingleScene( name_ )
    local tgtGO = GameObject.Find(name_)
    if isNull(tgtGO) then 
        printError("没找到目标 go: " .. tostring(name_) )
        return nil
    else 
        return tgtGO.transform
    end 
end


function IdolLive3D_MainForEdit:_SetGameObjectActive( goPath_, isActive_ )
    local go = GameObject.Find(goPath_)
    if isNotNull(go) then 
        KTool.SetActive( go, isActive_ == true )
    end
end


function IdolLive3D_MainForEdit._FindFirstChild( parentTF_, nameContain_, compType_, isOnlyActive_ )
    local comps = parentTF_.gameObject:GetComponentsInChildren(compType_,not isOnlyActive_) -- 包含自己
    for i=0, comps.Length-1 do 
        local comp = comps[i]
        if comp.gameObject ~= parentTF_.gameObject then 
            ---
            local isNameOK = true 
            if isNotNull(nameContain_) then 
                isNameOK = string.contains(string.lower(comp.name), string.lower(nameContain_), true) 
            end
            ---
            if isNotNull(comp) and isNameOK then 
                return comp
            end 
        end
    end
    printError("没找到 " .. tostring(nameContain_) )
    return nil
end




function IdolLive3D_MainForEdit.SetMainLight( rotation_, color_, intensity_ ) 

    local DirectionalLightGO = GameObject.Find("/Directional Light") -- 场景中真正在起作用的主光源
    local DirectionalLightTF = DirectionalLightGO.transform
    --local DirectionalLightTF = IdolLive3D_Utils.FindRootTransformInIdol3DScene("Directional Light") -- 场景中真正在起作用的主光源
    assert( isNotNull(DirectionalLightTF) )
    local DirectionalLight = KTool.GetComponent(DirectionalLightTF.gameObject, typeof(Light))
    assert(DirectionalLight)
    ---
    DirectionalLightTF.rotation = rotation_
    DirectionalLight.color = color_
    DirectionalLight.intensity = intensity_
end



