function IdolLive3D_MainForEdit:OnSwitchIdle( idleType_ )
    assert( idleType_ == IdleType.Type_100 or idleType_ == IdleType.Type_200 )
    local idle_100 = self.baseJson:Get_Idle_100()
    local idle_200 = self.baseJson:Get_Idle_200()
    local pos = (idleType_ == IdolLive3D_States.IdleType.Type_100) and idle_100.rolePos or idle_200.rolePos
    for _,tf in pairs(self.allRoleTFs) do 
        tf.position = pos
    end
end




return IdolLive3D_MainForEdit
